import json
from pathlib import Path

root = Path.home() / ".do_again" / "projects" / "41857a676462"
state = root / "state"
outbox = state / "browser_outbox"

report = {
    "browser_status": None,
    "pending_outbox": [],
    "callback_error": None,
    "recent_state_files": [],
}

status = state / "browser_status.json"
if status.exists():
    report["browser_status"] = json.loads(status.read_text())

if outbox.exists():
    for p in sorted(outbox.glob("*.json")):
        try:
            report["pending_outbox"].append({"name": p.name, "receipt": json.loads(p.read_text())})
        except Exception as exc:
            report["pending_outbox"].append({"name": p.name, "error": str(exc)})

err = state / "receipt_callback_error.json"
if err.exists():
    report["callback_error"] = json.loads(err.read_text())

for p in sorted(state.glob("*.json"), key=lambda p: p.stat().st_mtime, reverse=True)[:20]:
    report["recent_state_files"].append({
        "name": p.name,
        "mtime": p.stat().st_mtime,
        "size": p.stat().st_size,
    })

print(json.dumps(report, indent=2, sort_keys=True))
